scripts/prx/check-commit.mjs.source:
// PRX v1.1 commit-gate CLI — thin wrapper over commit-check.mjs
// (import-safe: importing this module runs nothing; SOL-PRX-008).
//
// usage:
//   node scripts/prx/check-commit.mjs <file>|-
//     [--governed] [--merge] [--bot] [--mode=audit|advisory|enforcing]
//     [--json]
//   node scripts/prx/check-commit.mjs --range <base>..<head> [--repo <dir>]
//     [--mode=...] [--json]
//
// Exit codes: 0 = no blocking findings for the mode; 1 = blocking findings
// (enforcing mode only); 2 = usage or tool error.
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { checkCommit } from "./commit-check.mjs";
import { parseModeState, resolveVerdict } from "./modes.mjs";

const MODULE_DIR = dirname(fileURLToPath(import.meta.url));

export function defaultMode() {
  return parseModeState(readFileSync(join(MODULE_DIR, "prx-mode.json"), "utf8"))
    .mode;
}

export function listCommits(repoDir, range) {
  // NUL-terminated records (-z): git forbids NUL in commit messages, so it
  // is the ONLY safe record delimiter. The v1.0-style 0x1e delimiter was an
  // audit bypass — a literal RS byte in a message truncated the record and
  // silently hid everything after it from the checker (review finding,
  // reproduced). The first four fields cannot contain newlines, so they
  // ride newline-separated ahead of the message.
  const raw = execFileSync(
    "git",
    ["-C", repoDir, "log", "-z", "--format=%H%n%P%n%an%n%ae%n%B", range],
    { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 }
  );
  const commits = [];
  for (const rec of raw.split("\0")) {
    if (rec === "") continue;
    const firstLines = rec.split("\n");
    if (firstLines.length < 5) {
      throw new Error(
        `malformed git log record (${firstLines.length} fields); refusing ` +
          "to audit a stream this parser cannot account for"
      );
    }
    const [sha, parents, authorName, authorEmail] = firstLines;
    const message = firstLines.slice(4).join("\n");
    commits.push({
      sha,
      isMerge: parents.trim().split(/\s+/).filter(Boolean).length > 1,
      // Honesty bound (remediation review): in range mode the bot signal
      // comes from the commit's OWN author fields, which the commit
      // author controls — it is a claimed identity, not authenticated
      // metadata. Its only power is SUPPRESSING the prefix finding, so a
      // forged "[bot]" grants nothing; enforcing-mode graduation should
      // bind this exemption to authenticated event metadata instead
      // (standard §10).
      authorIsBot: /\[bot\]/i.test(`${authorName} ${authorEmail}`),
      message,
    });
  }
  return commits;
}

function printFindings(label, findings) {
  for (const f of findings) {
    const loc = f.line === undefined ? "" : ` line ${f.line}`;
    process.stdout.write(
      `${f.level.toUpperCase()} ${f.rule}${label}${loc}: ${f.message}\n`
    );
  }
}

export function main(argv = process.argv.slice(2)) {
  const args = [...argv];
  const flags = { governed: false, merge: false, bot: false, json: false };
  let mode;
  let range;
  let repo = ".";
  let input;
  while (args.length > 0) {
    const a = args.shift();
    if (a === "--governed") flags.governed = true;
    else if (a === "--merge") flags.merge = true;
    else if (a === "--bot") flags.bot = true;
    else if (a === "--json") flags.json = true;
    else if (a.startsWith("--mode=")) mode = a.slice("--mode=".length);
    else if (a === "--range") range = args.shift();
    else if (a === "--repo") repo = args.shift();
    else if (input === undefined) input = a;
    else {
      process.stderr.write(`unexpected argument: ${a}\n`);
      return 2;
    }
  }
  try {
    mode = mode ?? defaultMode();
    const results = [];
    if (range !== undefined) {
      if (!/^[0-9a-fA-F~^]+\.\.[0-9a-fA-F~^]+$/.test(range ?? "")) {
        process.stderr.write("--range requires <baseSha>..<headSha>\n");
        return 2;
      }
      for (const c of listCommits(resolve(repo), range)) {
        results.push({
          id: c.sha.slice(0, 7),
          findings: checkCommit(c.message, {
            isMerge: c.isMerge,
            authorIsBot: c.authorIsBot,
          }),
        });
      }
    } else {
      if (input === undefined) {
        process.stderr.write(
          "usage: check-commit.mjs <file>|- [--governed] [--merge] [--bot] " +
            "[--mode=...] [--json] | --range <base>..<head> [--repo <dir>]\n"
        );
        return 2;
      }
      const text =
        input === "-"
          ? readFileSync(0, "utf8")
          : readFileSync(resolve(input), "utf8");
      results.push({
        id: input,
        findings: checkCommit(text, {
          governed: flags.governed,
          isMerge: flags.merge,
          authorIsBot: flags.bot,
        }),
      });
    }
    const all = results.flatMap(r => r.findings);
    const verdict = resolveVerdict(mode, all);
    // R3 honesty in the diagnostics themselves: the range audit validates
    // the governed schema only for commits that opt in (--governed) or
    // self-declare via a Run-Id/Evidence trailer; it does not decide which
    // commits ought to be governed.
    const governedScope =
      "opt-in: governed schema enforced only via --governed or a " +
      "Run-Id/Evidence trailer; this audit does not classify commits as " +
      "governed";
    if (flags.json) {
      process.stdout.write(
        `${JSON.stringify(
          range !== undefined
            ? { results, verdict, governedScope }
            : { results, verdict },
          null,
          2
        )}\n`
      );
    } else {
      for (const r of results) printFindings(` [${r.id}]`, r.findings);
      const errors = all.filter(f => f.level === "error").length;
      process.stdout.write(
        `PRX commit gate: ${errors} error(s), ${all.length - errors} ` +
          `advisory; mode=${mode}; exit=${verdict.exitCode}\n`
      );
      if (range !== undefined) {
        process.stdout.write(`note: governed scope is ${governedScope}\n`);
      }
    }
    return verdict.exitCode;
  } catch (err) {
    process.stderr.write(`prx/check-commit: ${err.message}\n`);
    return 2;
  }
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
) {
  process.exitCode = main();
}

scripts/prx/commit-check.mjs.source:
// PRX v1.1 commit-message checker — pure library, no CLI side effects.
// Replaces the rejected v1.0 first-word / whole-line-exemption heuristics
// (SOL-PRX-006, SOL-PRX-007) with a structural parser: subject, separator,
// body paragraphs, fences, URLs, and a formal trailer block are distinct
// structures, and exemption spans are narrow (the URL token itself, the
// parsed trailer block itself).
import {
  GOVERNED_TRAILER_KEYS,
  makeFinding,
  REF_MAX_LENGTH,
  REF_RE,
  RUN_ID_RE,
} from "./rules.mjs";

const SIZE_LIMIT = 1024 * 1024;
const CONVENTIONAL_TYPES = [
  "feat",
  "fix",
  "chore",
  "docs",
  "refactor",
  "test",
  "perf",
  "ci",
  "build",
  "style",
  "revert",
];
const CONVENTIONAL_RE = new RegExp(
  `^(${CONVENTIONAL_TYPES.join("|")})(\\([A-Za-z0-9][A-Za-z0-9._/-]*\\))?!?: \\S`
);
// Strip variant for the mood heuristic: identical prefix shape but it must
// NOT consume the first description character (review finding: a copula as
// the first description word was silently missed).
const PREFIX_STRIP_RE = new RegExp(
  `^(${CONVENTIONAL_TYPES.join("|")})(\\([A-Za-z0-9][A-Za-z0-9._/-]*\\))?!?: `
);
// A trailer line is "Key:" followed by an optional value. The empty-value
// form MUST parse as a trailer line so that "Run-Id:" is judged as an empty
// governed value instead of silently degrading the whole block to prose
// (v1.0 accepted exactly that bypass, Sol case C02).
const TRAILER_LINE_RE = /^([A-Za-z][A-Za-z0-9-]*):[ \t]*(.*)$/;
const TRAILER_CONTINUATION_RE = /^[ \t]+\S/;
const URL_RE = /https?:\/\/[^\s<>]+/g;
const FENCE_RE = /^(`{3,}|~{3,})/;
// Evidence grammar (REF_RE) and its length cap are shared with the body
// checker via rules.mjs so the two surfaces cannot drift (Sol case C09).
const CO_AUTHOR_RE = /^[^<>]+ <[^<>@\s]+@[^<>@\s]+\.[A-Za-z]{2,}>$/;
const COPULA_RE = /(^|\s)(is|are|was|were)(\s|$)/;

export function parseCommitMessage(raw) {
  const text = raw.replace(/\r\n/g, "\n").replace(/\n+$/, "");
  const lines = text.split("\n");
  const subject = lines[0] ?? "";

  let bodyStart = 1;
  let separatorBlanks = 0;
  while (bodyStart < lines.length && lines[bodyStart].trim() === "") {
    separatorBlanks += 1;
    bodyStart += 1;
  }
  const bodyLines = lines
    .slice(bodyStart)
    .map((textLine, i) => ({ text: textLine, line: bodyStart + i + 1 }));

  // Fence tracking over the body.
  let inFence = false;
  let fenceMarker = "";
  for (const l of bodyLines) {
    const m = l.text.match(FENCE_RE);
    if (!m) {
      l.inFence = inFence;
      continue;
    }
    if (!inFence) {
      inFence = true;
      fenceMarker = m[1][0];
      l.inFence = true;
    } else if (m[1][0] === fenceMarker) {
      inFence = false;
      l.inFence = true;
    } else {
      l.inFence = true;
    }
  }
  const unclosedFence = inFence;

  // Formal trailer block: the final non-blank run of body lines, outside any
  // fence, in which every line is trailer-shaped or a continuation. This is
  // a documented strict adaptation of git interpret-trailers.
  let trailers = null;
  if (!unclosedFence && bodyLines.length > 0) {
    let end = bodyLines.length - 1;
    while (end >= 0 && bodyLines[end].text.trim() === "") end -= 1;
    let start = end;
    while (start >= 0 && bodyLines[start].text.trim() !== "") start -= 1;
    start += 1;
    if (end >= start && start >= 0) {
      const block = bodyLines.slice(start, end + 1);
      const allShaped =
        block.every(
          l =>
            TRAILER_LINE_RE.test(l.text) || TRAILER_CONTINUATION_RE.test(l.text)
        ) &&
        !block[0].inFence &&
        TRAILER_LINE_RE.test(block[0].text);
      if (allShaped) {
        const parsed = [];
        for (const l of block) {
          const m = l.text.match(TRAILER_LINE_RE);
          if (m) {
            parsed.push({ key: m[1], value: m[2].trim(), line: l.line });
          } else if (parsed.length > 0) {
            parsed[parsed.length - 1].value += ` ${l.text.trim()}`;
          }
        }
        trailers = {
          entries: parsed,
          startLine: block[0].line,
          blockLines: block.map(l => l.line),
        };
      }
    }
  }

  return { subject, separatorBlanks, bodyLines, trailers, unclosedFence };
}

function trailerLines(parsed) {
  // The whole parsed trailer block is the exemption span, continuation
  // lines included (the standard's wording is the contract here).
  return new Set(parsed.trailers?.blockLines ?? []);
}

export function checkCommit(raw, opts = {}) {
  const findings = [];
  if (typeof raw !== "string" || raw.length > SIZE_LIMIT) {
    findings.push(
      // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
      makeFinding("PRX-C-SIZE", "commit message exceeds the 1 MiB bound")
    );
    return findings;
  }
  const parsed = parseCommitMessage(raw);
  const { subject, separatorBlanks, bodyLines, trailers, unclosedFence } =
    parsed;
  const hasBody = bodyLines.some(l => l.text.trim() !== "");

  // PRX-C-SUBJECT
  if (subject.trim() === "") {
    // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
    findings.push(makeFinding("PRX-C-SUBJECT", "subject line is empty", 1));
  } else {
    if (subject !== subject.trim()) {
      findings.push(
        makeFinding(
          "PRX-C-SUBJECT",
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          "subject has leading or trailing whitespace",
          1
        )
      );
    }
    if (/\.\s*$/.test(subject)) {
      findings.push(
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        makeFinding("PRX-C-SUBJECT", "subject ends with a period", 1)
      );
    }
    // eslint-disable-next-line no-control-regex
    if (/[\u0000-\u0008\u000b-\u001f\u007f]/.test(subject)) {
      findings.push(
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        makeFinding("PRX-C-SUBJECT", "subject contains control characters", 1)
      );
    }
  }

  // Exemptions come from commit topology or authenticated metadata supplied
  // by the caller — never from the subject text (Sol case C03).
  const exemptFromPrefix =
    opts.isMerge === true ||
    opts.authorIsBot === true ||
    isGeneratedRevert(subject, bodyLines);

  // PRX-C-FIXUP
  if (/^(fixup!|squash!)/.test(subject)) {
    findings.push(
      makeFinding(
        "PRX-C-FIXUP",
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        "fixup!/squash! commit must be autosquashed before it reaches a " +
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          "mainline range",
        1
      )
    );
  } else if (!exemptFromPrefix && !CONVENTIONAL_RE.test(subject)) {
    findings.push(
      makeFinding(
        "PRX-C-PREFIX",
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        "subject does not match the repository convention " +
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          '"type(scope): summary"; merge/bot/revert exemptions require ' +
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          "topology or authenticated metadata",
        1
      )
    );
  }

  // PRX-C-SEPARATOR
  if (hasBody && separatorBlanks !== 1) {
    findings.push(
      makeFinding(
        "PRX-C-SEPARATOR",
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        `exactly one blank line must separate subject and body ` +
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          `(found ${separatorBlanks})`,
        2
      )
    );
  }

  // PRX-C-LENGTH (advisory)
  if (subject.length > 72) {
    findings.push(
      makeFinding(
        "PRX-C-LENGTH",
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        `subject is ${subject.length} characters (advisory threshold 72)`,
        1
      )
    );
  }

  // PRX-C-FENCE
  if (unclosedFence) {
    findings.push(
      // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
      makeFinding("PRX-C-FENCE", "unclosed code fence in commit body")
    );
  }

  // PRX-C-WRAP (advisory) — narrow exemption spans only.
  const exemptLines = trailerLines(parsed);
  for (const l of bodyLines) {
    if (l.inFence || exemptLines.has(l.line)) continue;
    if (/^\s*\|/.test(l.text)) continue;
    const withoutUrls = l.text.replace(URL_RE, "");
    if (withoutUrls.length > 72) {
      findings.push(
        makeFinding(
          "PRX-C-WRAP",
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          `body line is ${l.text.length} columns ` +
            // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
            `(${withoutUrls.length} excluding URL tokens; advisory limit 72)`,
          l.line
        )
      );
    }
  }

  // PRX-C-TRAILER — formal grammar for any parsed trailer block.
  const governedPresent =
    trailers !== null &&
    trailers.entries.some(e => e.key === "Run-Id" || e.key === "Evidence");
  if (trailers) {
    const counts = new Map();
    for (const e of trailers.entries) {
      counts.set(e.key, (counts.get(e.key) ?? 0) + 1);
      if (e.value === "") {
        findings.push(
          makeFinding(
            "PRX-C-TRAILER",
            // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
            `trailer "${e.key}" has an empty value`,
            e.line
          )
        );
      }
    }
    for (const key of GOVERNED_TRAILER_KEYS) {
      if (key !== "Co-Authored-By" && (counts.get(key) ?? 0) > 1) {
        findings.push(
          makeFinding(
            "PRX-C-TRAILER",
            // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
            `governed trailer "${key}" appears ${counts.get(key)} times ` +
              // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
              "(exactly once required)"
          )
        );
      }
    }
    // Co-Authored-By value grammar is validated WHEREVER the trailer
    // appears — a malformed lone Co-Authored-By is a trailer-grammar error
    // and never activates the governed Run-Id/Evidence requirements (R3).
    for (const e of trailers.entries) {
      if (e.key === "Co-Authored-By" && !CO_AUTHOR_RE.test(e.value)) {
        findings.push(
          makeFinding(
            "PRX-C-TRAILER",
            // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
            `Co-Authored-By "${truncate(e.value)}" is not "Name <email>"`,
            e.line
          )
        );
      }
    }
  }

  // PRX-C-GOV — the governed-scope predicate: explicit opt-in from the
  // caller, or the commit declares itself governed by carrying a governed
  // identity trailer. Whether a commit OUGHT to be governed is a reviewer
  // rule; this library enforces the schema once the scope applies.
  const governed = opts.governed === true || governedPresent;
  if (governed) {
    const byKey = key => (trailers?.entries ?? []).filter(e => e.key === key);
    const runIds = byKey("Run-Id");
    if (runIds.length !== 1) {
      findings.push(
        makeFinding(
          "PRX-C-GOV",
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          `governed commit must carry Run-Id exactly once (found ${runIds.length})`
        )
      );
    } else if (!RUN_ID_RE.test(runIds[0].value)) {
      findings.push(
        makeFinding(
          "PRX-C-GOV",
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          `Run-Id "${truncate(runIds[0].value)}" does not match ` +
            // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
            "ONE-YYYYMMDD-TOKEN",
          runIds[0].line
        )
      );
    }
    const evidences = byKey("Evidence");
    if (evidences.length !== 1) {
      findings.push(
        makeFinding(
          "PRX-C-GOV",
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          `governed commit must carry Evidence exactly once (found ${evidences.length})`
        )
      );
    } else {
      const v = evidences[0].value;
      if (v.length > REF_MAX_LENGTH || !REF_RE.test(v)) {
        findings.push(
          makeFinding(
            "PRX-C-GOV",
            // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
            `Evidence "${truncate(v)}" is not a bounded run/ or docs/ ` +
              // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
              "reference (or UNKNOWN)",
            evidences[0].line
          )
        );
      }
    }
    // Presence only: the value grammar is already enforced by the
    // always-on PRX-C-TRAILER pass above, governed or not (R3).
    if (byKey("Co-Authored-By").length === 0) {
      findings.push(
        makeFinding(
          "PRX-C-GOV",
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          "governed commit must carry at least one Co-Authored-By trailer"
        )
      );
    }
  }

  // PRX-C-MOOD (heuristic, declared) — a copula in the subject description
  // suggests indicative narration. This is the ONLY machine mood check;
  // imperative mood in general is a reviewer rule (SOL-PRX-007 honesty).
  const description = subject.replace(PREFIX_STRIP_RE, "").trim() || subject;
  if (COPULA_RE.test(description)) {
    findings.push(
      makeFinding(
        "PRX-C-MOOD",
        // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
        "subject reads as indicative (copula heuristic); write the summary " +
          // Stryker disable next-line StringLiteral: diagnostic message text (R8 exclusion)
          "as an instruction",
        1
      )
    );
  }

  return findings;
}

// A git-generated revert is recognized by BOTH the generated subject shape
// and the generated body marker, never the subject alone.
function isGeneratedRevert(subject, bodyLines) {
  return (
    /^Revert "/.test(subject) &&
    bodyLines.some(l => /^This reverts commit [0-9a-f]{7,40}\b/.test(l.text))
  );
}

function truncate(s) {
  return s.length > 60 ? `${s.slice(0, 57)}...` : s;
}

scripts/prx/modes.mjs.source:
// PRX v1.1 rollout modes (SOL-PRX-010). The committed mode state is
// scripts/prx/prx-mode.json; CI reads it from the TRUSTED policy source, so
// a pull request cannot flip its own enforcement level. Transitions
// (audit -> advisory -> enforcing) are owner-authorized reviewed changes to
// that file plus, for enforcing, the separate owner ruleset action that
// makes the check required — this lane never adds itself to the ruleset.
import { ruleClass } from "./rules.mjs";

export const MODES = Object.freeze(["audit", "advisory", "enforcing"]);

// Enforcing mode may block ONLY on rules in this list (Section 12 of the
// execution contract: "explicitly approved deterministic blocking rules").
// Advisory- and heuristic-class rules can never appear here; ruleClass()
// guards against registry drift at module load.
export const APPROVED_BLOCKING = Object.freeze(
  [
    "PRX-C-SIZE",
    "PRX-C-SUBJECT",
    "PRX-C-PREFIX",
    "PRX-C-SEPARATOR",
    "PRX-C-FENCE",
    "PRX-C-TRAILER",
    "PRX-C-GOV",
    "PRX-C-FIXUP",
    "PRX-B-SIZE",
    "PRX-B-VISIBLE",
    "PRX-B-SECTION-MISSING",
    "PRX-B-SECTION-DUP",
    "PRX-B-SECTION-EMPTY",
    "PRX-B-CAPSULE",
  ].filter(id => {
    if (ruleClass(id) !== "deterministic") {
      throw new Error(
        `APPROVED_BLOCKING may only contain deterministic rules; ${id} is ` +
          ruleClass(id)
      );
    }
    return true;
  })
);

export function parseModeState(json) {
  let state;
  try {
    state = JSON.parse(json);
  } catch {
    throw new Error("prx-mode.json is not valid JSON");
  }
  if (state?.version !== 1 || !MODES.includes(state?.mode)) {
    throw new Error(
      `prx-mode.json must be {"version":1,"mode":"audit|advisory|enforcing"}`
    );
  }
  return state;
}

// The verdict: audit and advisory NEVER produce a blocking exit; enforcing
// blocks only on approved deterministic findings. Tool crashes are handled
// by the CLI wrappers with exit 2 and are outside this function.
export function resolveVerdict(mode, findings) {
  if (!MODES.includes(mode)) throw new Error(`unknown PRX mode: ${mode}`);
  const blocking =
    mode === "enforcing"
      ? findings.filter(
          f => f.level === "error" && APPROVED_BLOCKING.includes(f.rule)
        )
      : [];
  return { mode, blocking, exitCode: blocking.length > 0 ? 1 : 0 };
}

scripts/prx/resolve-range.mjs.source:
// PRX v1.1 audit-range resolution — FAIL CLOSED (remediation R2).
// Replaces the workflow's rejected fail-open pattern
//   git merge-base "$BASE" "$HEAD" || echo "$BASE"
// which silently substituted a different audit range whenever merge-base
// failed. This module is the exact code CI executes (the workflow calls it
// from the selected policy tree), not a bash mirror, so its tests cover the
// shipped behavior directly. Import-safe: importing runs nothing.
import { execFileSync } from "node:child_process";
import { resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { SHA40_RE } from "./rules.mjs";

function runGit(repoDir, args) {
  return execFileSync("git", ["-C", repoDir, ...args], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
}

// Resolves the merge base of the two authenticated event SHAs, or throws.
// Every failure mode is a hard error — a merge-base failure must produce a
// red tool failure and must never silently substitute another range.
// deps.git is injectable ONLY so tests can prove the output validation
// rejects malformed git output; production callers pass nothing.
export function resolveAuditRange(repoDir, baseSha, headSha, deps = {}) {
  const git = deps.git ?? runGit;
  for (const [name, sha] of [
    ["base", baseSha],
    ["head", headSha],
  ]) {
    if (typeof sha !== "string" || !SHA40_RE.test(sha)) {
      throw new Error(
        `${name} SHA ${JSON.stringify(sha)} is not a full 40-hex commit SHA`
      );
    }
  }
  for (const [name, sha] of [
    ["base", baseSha],
    ["head", headSha],
  ]) {
    try {
      git(repoDir, ["cat-file", "-e", `${sha}^{commit}`]);
    } catch {
      throw new Error(
        `${name} commit ${sha} does not exist in the repository at ${repoDir}`
      );
    }
  }
  let mergeBase;
  try {
    mergeBase = git(repoDir, ["merge-base", baseSha, headSha]).trim();
  } catch {
    throw new Error(
      `unable to resolve the merge base of ${baseSha} and ${headSha} (unrelated histories or corrupt repository)`
    );
  }
  if (!SHA40_RE.test(mergeBase)) {
    throw new Error(
      `merge-base output ${JSON.stringify(mergeBase.slice(0, 80))} is not a full 40-hex commit SHA`
    );
  }
  try {
    git(repoDir, ["merge-base", "--is-ancestor", mergeBase, headSha]);
  } catch {
    throw new Error(
      `resolved merge base ${mergeBase} is not an ancestor of head ${headSha}`
    );
  }
  return { mergeBase, range: `${mergeBase}..${headSha}` };
}

// CLI: prints the merge base to stdout on success (exit 0); resolution
// failures exit 1 with the reason on stderr; usage errors exit 2.
export function main(argv = process.argv.slice(2)) {
  const args = [...argv];
  let repo;
  let base;
  let head;
  while (args.length > 0) {
    const a = args.shift();
    if (a === "--repo") repo = args.shift();
    else if (a === "--base") base = args.shift();
    else if (a === "--head") head = args.shift();
    else {
      process.stderr.write(`unexpected argument: ${a}\n`);
      return 2;
    }
  }
  if (repo === undefined || base === undefined || head === undefined) {
    process.stderr.write(
      "usage: resolve-range.mjs --repo <dir> --base <sha40> --head <sha40>\n"
    );
    return 2;
  }
  try {
    const { mergeBase } = resolveAuditRange(resolve(repo), base, head);
    process.stdout.write(`${mergeBase}\n`);
    return 0;
  } catch (err) {
    process.stderr.write(`prx/resolve-range: ${err.message}\n`);
    return 1;
  }
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
) {
  process.exitCode = main();
}

scripts/prx/policy-source.mjs.source:
// PRX v1.1 trusted-policy selection (SOL-PRX-004). CI checks out the
// event's BASE SHA into a separate directory and asks this module which
// policy tree may produce the verdict. Pull-request head content is data,
// never policy. scripts/prx/trusted-boundary.test.ts mutates a simulated
// head checker and proves the selection (and the selected bytes) do not
// change.
import { existsSync } from "node:fs";
import { join } from "node:path";

const POLICY_MARKER = join("scripts", "prx", "check-commit.mjs");

export function selectPolicySource({ trustedDir, headDir }) {
  if (trustedDir && existsSync(join(trustedDir, POLICY_MARKER))) {
    return {
      dir: trustedDir,
      trusted: true,
      reason: "policy loaded from the trusted base ref",
    };
  }
  return {
    dir: headDir,
    trusted: false,
    reason:
      "bootstrap: policy is absent on the base ref; the head copy runs " +
      "explicitly UNTRUSTED and the lane stays audit-only",
  };
}

// NUL-delimited file-list transfer (SOL-PRX-017): safe for filenames
// containing spaces, tabs, newlines, and leading hyphens.
export function parseNulList(input) {
  return input.split("\0").filter(name => name.length > 0);
}

scripts/prx/rules.mjs.source:
// PRX v1.1 rule registry — every rule the lane can emit, with its
// enforcement class. The class is the only registry field the decision
// path consumes (level derivation + APPROVED_BLOCKING gating); display
// titles and surface labels live in rule-metadata.mjs, keyed by the same
// ids (rules.test.ts pins the key sets equal). The standard document
// (docs/verification/prx/PRX-STANDARD-v1.1.md) and the source-trace matrix
// (docs/verification/prx/source-trace-matrix.csv) key off these ids; tests
// pin fixtures to exact sets of them. Classes:
//   deterministic — machine-provable structure; may block in enforcing mode
//                   when listed in APPROVED_BLOCKING (modes.mjs)
//   advisory      — measurable but policy-soft (repo practice diverges, or
//                   thresholds are owner-tunable); never blocks
//   heuristic     — declared approximation of a semantic property; never
//                   blocks and never claims certainty
export const RULES = Object.freeze({
  // Commit-message rules
  "PRX-C-SIZE": { class: "deterministic" },
  "PRX-C-SUBJECT": { class: "deterministic" },
  "PRX-C-PREFIX": { class: "deterministic" },
  "PRX-C-SEPARATOR": { class: "deterministic" },
  "PRX-C-LENGTH": { class: "advisory" },
  "PRX-C-WRAP": { class: "advisory" },
  "PRX-C-FENCE": { class: "deterministic" },
  "PRX-C-TRAILER": { class: "deterministic" },
  "PRX-C-GOV": { class: "deterministic" },
  "PRX-C-FIXUP": { class: "deterministic" },
  "PRX-C-MOOD": { class: "heuristic" },

  // PR-body rules (section subcodes per remediation R5: missing,
  // duplicate, and empty are independent blocking conditions)
  "PRX-B-SIZE": { class: "deterministic" },
  "PRX-B-VISIBLE": { class: "deterministic" },
  "PRX-B-SECTION-MISSING": { class: "deterministic" },
  "PRX-B-SECTION-DUP": { class: "deterministic" },
  "PRX-B-SECTION-EMPTY": { class: "deterministic" },
  "PRX-B-ORDER": { class: "advisory" },
  "PRX-B-CAPSULE": { class: "deterministic" },
  "PRX-B-EXT": { class: "advisory" },
  "PRX-B-STRUCTURE": { class: "advisory" },
  "PRX-B-FENCE": { class: "advisory" },
  "PRX-B-COMMENT": { class: "advisory" },
});

export const GOVERNED_TRAILER_KEYS = Object.freeze([
  "Run-Id",
  "Evidence",
  "Co-Authored-By",
]);

// Shared value grammars — single source for both checkers so the commit
// and body surfaces cannot drift apart (review finding: the Evidence
// length cap existed only on the commit side).
export const RUN_ID_RE = /^ONE-[0-9]{8}-[A-Z0-9]+$/;
export const SHA40_RE = /^[0-9a-f]{40}$/;
export const SCOPE_RE = /^TOS-[0-9]+$/;
export const REF_RE =
  /^(UNKNOWN|run\/ONE-[0-9]{8}-[A-Z0-9]+(\/[A-Za-z0-9._-]+){1,5}|docs\/[A-Za-z0-9._-]+(\/[A-Za-z0-9._-]+){0,5})$/;
export const REF_MAX_LENGTH = 120;

export function ruleClass(id) {
  const rule = RULES[id];
  if (!rule) throw new Error(`unknown PRX rule id: ${id}`);
  return rule.class;
}

export function makeFinding(rule, message, line) {
  const cls = ruleClass(rule);
  return {
    rule,
    class: cls,
    level: cls === "deterministic" ? "error" : "advisory",
    message,
    ...(line === undefined ? {} : { line }),
  };
}

scripts/prx/body-check.test.ts.source:
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { checkBody, extractProse, REQUIRED_SECTIONS } from "./body-check.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const fixture = (name: string) =>
  readFileSync(join(HERE, "fixtures/body", name), "utf8");
const rules = (findings: { rule: string }[]) =>
  findings.map(f => f.rule).sort();

const healthy = fixture("healthy.md");

describe("healthy bodies", () => {
  it("full live-template body with capsule is clean", () => {
    expect(checkBody(healthy)).toEqual([]);
  });

  it("capsule is optional: live-template body without one is clean", () => {
    expect(checkBody(fixture("healthy-no-capsule.md"))).toEqual([]);
  });

  it("lists, checkboxes, and tables are allowed structure", () => {
    const withTable = healthy.replace(
      "## Post-deployment validation\n\nnone",
      "## Post-deployment validation\n\n| check | result |\n| --- | --- |\n| smoke | pass |"
    );
    expect(checkBody(withTable)).toEqual([]);
  });
});

describe("live-template section schema", () => {
  it("validates the 14 sections of .github/pull_request_template.md", () => {
    expect(REQUIRED_SECTIONS.length).toBe(14);
  });

  it("flags a missing section with the MISSING subcode", () => {
    const body = healthy.replace(/## Bundle impact\n\nnone\n/, "");
    const f = checkBody(body);
    expect(f.some(x => x.rule === "PRX-B-SECTION-MISSING")).toBe(true);
    expect(f.some(x => x.rule === "PRX-B-SECTION-DUP")).toBe(false);
  });

  it("flags a duplicate section with the DUP subcode", () => {
    const f = checkBody(`${healthy}\n## Tests\n\nAgain.\n`);
    expect(
      f.filter(x => x.rule === "PRX-B-SECTION-DUP" && x.level === "error")
        .length
    ).toBe(1);
    expect(f.some(x => x.rule === "PRX-B-SECTION-MISSING")).toBe(false);
  });

  it("flags an empty section with the EMPTY subcode", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact"
    );
    const f = checkBody(body);
    expect(f.some(x => x.rule === "PRX-B-SECTION-EMPTY")).toBe(true);
  });

  it("out-of-order sections are advisory, not errors", () => {
    const body = healthy
      .replace("## Notion context\n\nnone\n\n", "")
      .concat("\n## Notion context\n\nnone\n");
    const f = checkBody(body);
    const order = f.filter(x => x.rule === "PRX-B-ORDER");
    expect(order.length).toBe(1);
    expect(order[0].level).toBe("advisory");
  });

  it("the engineering-federation evidence heading is an allowed extension", () => {
    const f = checkBody(
      `${healthy}\n## Evidence record (engineering-federation §21.3)\n\nrecord: filled\n`
    );
    expect(f.filter(x => x.rule === "PRX-B-EXT")).toEqual([]);
  });
});

describe("capsule schema (strict when present)", () => {
  it("rejects two capsules", () => {
    const capsule = healthy.slice(0, healthy.indexOf("```\n", 4) + 4);
    const f = checkBody(capsule + healthy);
    expect(f.some(x => x.rule === "PRX-B-CAPSULE")).toBe(true);
  });

  it("rejects an unknown key as a non-key line", () => {
    const body = healthy.replace(
      "Evidence: UNKNOWN",
      "Evidence: UNKNOWN\nSurprise: extra"
    );
    const f = checkBody(body);
    expect(f.some(x => x.rule === "PRX-B-CAPSULE")).toBe(true);
  });

  it("enforces the size bound", () => {
    expect(rules(checkBody("x".repeat(1024 * 1024 + 1)))).toEqual([
      "PRX-B-SIZE",
    ]);
  });
});

describe("prose extraction for the style layer (R4: parent-aware)", () => {
  it("decodes entities and skips code/list content", () => {
    const prose = extractProse(
      "## A\n\nNarrative &mdash; here.\n\n```\ncode line\n```\n\n- item\n"
    );
    expect(prose).toContain("Narrative — here.");
    expect(prose).not.toContain("code line");
    // The list item's text must be absent, not merely the code text.
    expect(prose).not.toContain("item");
  });

  it("includes ordinary narrative paragraphs and preserves decoded entities", () => {
    const prose = extractProse(
      "## Purpose and scope\n\nFirst narrative sentence.\n\nSecond &amp; third."
    );
    expect(prose).toContain("First narrative sentence.");
    expect(prose).toContain("Second & third.");
  });

  it("excludes bullet text and NESTED bullet text", () => {
    const prose = extractProse(
      "Narrative stays.\n\n- top bullet text\n  - nested bullet text\n\n" +
        "- outer item\n\n  paragraph nested inside a loose list item\n"
    );
    expect(prose).toContain("Narrative stays.");
    expect(prose).not.toContain("top bullet text");
    expect(prose).not.toContain("nested bullet text");
    expect(prose).not.toContain("paragraph nested inside a loose list item");
  });

  it("excludes checkbox (task-list) text", () => {
    const prose = extractProse(
      "Narrative stays.\n\n- [ ] CI green checkbox field\n- [x] Owner authorized\n"
    );
    expect(prose).not.toContain("CI green checkbox field");
    expect(prose).not.toContain("Owner authorized");
  });

  it("excludes table cells", () => {
    const prose = extractProse(
      "Narrative stays.\n\n| header cell | other |\n| --- | --- |\n| body cell text | more |\n"
    );
    expect(prose).toContain("Narrative stays.");
    expect(prose).not.toContain("header cell");
    expect(prose).not.toContain("body cell text");
  });

  it("excludes blockquoted text", () => {
    const prose = extractProse(
      "Narrative stays.\n\n> quoted sentence that is not narrative.\n"
    );
    expect(prose).not.toContain("quoted sentence");
  });

  it("excludes raw HTML", () => {
    const prose = extractProse(
      "Narrative stays.\n\n<div>html block sentence.</div>\n"
    );
    expect(prose).not.toContain("html block sentence");
  });

  it("excludes capsule values and evidence-record YAML blocks", () => {
    const prose = extractProse(
      "```\nScope: TOS-123\nRun-Id: ONE-20260812-PRX\n```\n\nNarrative stays.\n\n" +
        "```yaml\noutcome: shipped\nverification: full\n```\n"
    );
    expect(prose).toContain("Narrative stays.");
    expect(prose).not.toContain("TOS-123");
    expect(prose).not.toContain("outcome: shipped");
  });
});

describe("meaningful visible section content (R5)", () => {
  const withSection = (content: string) =>
    healthy.replace(
      "## Bundle impact\n\nnone",
      `## Bundle impact\n\n${content}`
    );
  const emptyFor = (content: string) =>
    checkBody(withSection(content)).filter(
      x => x.rule === "PRX-B-SECTION-EMPTY"
    );

  const rejected: Array<[string, string]> = [
    ["whitespace-only HTML entity of nothing", "<!-- filled later -->"],
    ["an empty fenced block", "```\n```"],
    ["a thematic break", "***"],
    ["empty HTML", "<div></div>"],
    ["an image with empty alternative text", "![](evidence.png)"],
    ["a link with no visible label", "[](https://example.com)"],
    ["an empty list item", "-"],
    ["an empty table", "|  |  |\n| --- | --- |\n|  |  |"],
    ["a subheading with no following content", "### details"],
  ];
  for (const [label, content] of rejected) {
    it(`rejects ${label}`, () => {
      expect(emptyFor(content).length).toBe(1);
    });
  }

  const accepted: Array<[string, string]> = [
    ["visible prose", "Real content here."],
    ["the exact permitted none convention", "none"],
    ["a non-empty list", "- one real item"],
    ["a non-empty checklist", "- [ ] pending item"],
    ["a non-empty table", "| a | b |\n| --- | --- |\n| c | d |"],
    ["a visible link label", "[evidence run](https://example.com/run)"],
    ["a visible image alternative text", "![feed screenshot](feed.png)"],
    ["a populated structured evidence block", "```yaml\noutcome: shipped\n```"],
  ];
  for (const [label, content] of accepted) {
    it(`accepts ${label}`, () => {
      expect(emptyFor(content)).toEqual([]);
    });
  }
});

describe("mutation-hardening (targeted survivor kills)", () => {
  it("accepts a body at exactly the 1 MiB bound", () => {
    const padded = healthy + "x".repeat(1024 * 1024 - healthy.length);
    const f = checkBody(padded);
    expect(f.some(x => x.rule === "PRX-B-SIZE")).toBe(false);
  });

  it("an HTML block with visible text after the comment is NOT a comment", () => {
    const f = checkBody("<!-- note --> visible tail\n");
    expect(f.some(x => x.rule === "PRX-B-VISIBLE")).toBe(false);
  });

  it("depth-3 subheadings are not sections and not extensions", () => {
    const body = healthy.replace(
      "## Post-deployment validation\n\nnone",
      "## Post-deployment validation\n\nnone\n\n### sub-detail\n\nMore."
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("moving the FIRST template section to the end still trips order", () => {
    const body = healthy
      .replace(
        "## Purpose and scope\n\nAdd the PRX audit lane fixture body.\n\n",
        ""
      )
      .concat("\n## Purpose and scope\n\nMoved to the end.\n");
    const f = checkBody(body);
    expect(f.some(x => x.rule === "PRX-B-ORDER")).toBe(true);
  });

  it("nested plain lists are allowed structure, not disguised structure", () => {
    const body = healthy.replace(
      "- Added/changed tests: none",
      "- Added/changed tests:\n  - none listed"
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("HTML inside a labeled code fence is code, not a rendered list", () => {
    const body = healthy.replace(
      "## Post-deployment validation\n\nnone",
      "## Post-deployment validation\n\n```html\n<ul><li>sample</li></ul>\n```"
    );
    const f = checkBody(body);
    expect(f.some(x => x.rule === "PRX-B-STRUCTURE")).toBe(false);
  });

  it("extractProse returns empty for oversized input and text at the bound", () => {
    expect(extractProse("y".repeat(1024 * 1024 + 1))).toBe("");
    const atBound = "words here" + " pad".repeat(10);
    expect(extractProse(atBound)).toContain("words here");
  });
});

describe("entity-dash alternatives (gstack completeness pass)", () => {
  for (const entity of [
    "&ndash;",
    "&#8212;",
    "&#8211;",
    "&#x2014;",
    "&#x2013;",
  ]) {
    it(`detects ${entity}`, () => {
      const f = checkBody(`${healthy}\nAn encoded ${entity} dash.\n`);
      expect(f.some(x => x.rule === "PRX-B-STRUCTURE")).toBe(true);
    });
  }
});

describe("review-pass regressions", () => {
  it("deep blockquote nesting yields a finding, never a crash", () => {
    const f = checkBody(">".repeat(20000));
    expect(Array.isArray(f)).toBe(true);
    expect(f.length).toBeGreaterThan(0);
  });

  it("extractProse survives deep nesting", () => {
    expect(typeof extractProse(">".repeat(20000))).toBe("string");
  });

  it("capsule Evidence over the shared length cap fails even if shaped", () => {
    const long = `docs/${"a/".repeat(2)}${"b".repeat(120)}`;
    const body = healthy.replace("Evidence: UNKNOWN", `Evidence: ${long}`);
    const f = checkBody(body);
    expect(f.some(x => x.rule === "PRX-B-CAPSULE")).toBe(true);
  });

  it("REQUIRED_SECTIONS matches the live PR template exactly (drift guard)", () => {
    const template = readFileSync(
      join(HERE, "../../.github/pull_request_template.md"),
      "utf8"
    );
    const headings = [...template.matchAll(/^## (.+)$/gm)].map(m => m[1]);
    expect(headings).toEqual([...REQUIRED_SECTIONS]);
  });
});

describe("mutation-hardening round 3 (R8 survivors)", () => {
  it("an HTML comment with trailing whitespace is still a comment", () => {
    const f = checkBody("<!-- note --> ");
    expect(f.some(x => x.rule === "PRX-B-VISIBLE")).toBe(true);
  });

  it("an HTML block ending in a comment but starting with markup is NOT a comment", () => {
    const f = checkBody("<div>hello</div><!-- t -->");
    expect(f.some(x => x.rule === "PRX-B-VISIBLE")).toBe(false);
  });

  it("an inline HTML comment inside a section heading does not change its text", () => {
    const body = healthy.replace("## Tests", "## Tests<!-- note -->");
    expect(checkBody(body)).toEqual([]);
  });

  it("extractProse: exact text — images add nothing, inline joins are seamless, paragraphs join with blank lines", () => {
    expect(extractProse("![alt text](x.png)")).toBe("");
    expect(extractProse("Hello **world** now.")).toBe("Hello world now.");
    expect(extractProse("One a.\n\nTwo b.")).toBe("One a.\n\nTwo b.");
  });

  it("footnote definitions are not section content and footnote references carry no visible text", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n[^1]\n\n[^1]: note text here."
    );
    const empt = checkBody(body).filter(x => x.rule === "PRX-B-SECTION-EMPTY");
    expect(empt.length).toBe(1);
  });

  it("a benign HTML comment (no heading, no line-anchored capsule key) is not flagged", () => {
    expect(
      checkBody(healthy + "\n<!-- tail## note microScope: lens -->\n")
    ).toEqual([]);
  });

  it("a heading-only comment (no capsule keys) trips PRX-B-COMMENT", () => {
    const f = checkBody(healthy + "\n<!--\n## Hidden heading\n-->\n");
    expect(f.some(x => x.rule === "PRX-B-COMMENT")).toBe(true);
  });

  it("blank and whitespace-only capsule lines are ignored", () => {
    const body = healthy.replace("Scope: TOS-123\n", "Scope: TOS-123\n\n \n");
    expect(checkBody(body)).toEqual([]);
  });

  it("capsule values are compared trimmed (trailing whitespace tolerated)", () => {
    const body = healthy.replace("Scope: TOS-123\n", "Scope: TOS-123 \n");
    expect(checkBody(body)).toEqual([]);
  });

  it("a missing capsule key reports 'is missing', not a grammar error", () => {
    const body = healthy.replace("Ledger: UNKNOWN\n", "");
    const f = checkBody(body).filter(x => x.rule === "PRX-B-CAPSULE");
    expect(f.length).toBe(1);
    expect(f[0].message).toContain('capsule key "Ledger" is missing');
  });

  it("an empty capsule value reports 'has no value', not a grammar error", () => {
    const body = healthy.replace("Ledger: UNKNOWN", "Ledger:");
    const f = checkBody(body).filter(x => x.rule === "PRX-B-CAPSULE");
    expect(f.length).toBe(1);
    expect(f[0].message).toContain("has no value");
  });

  it("a placeholder capsule value reports the placeholder, not a grammar error", () => {
    const body = healthy.replace("Scope: TOS-123", "Scope: TBD");
    const f = checkBody(body).filter(x => x.rule === "PRX-B-CAPSULE");
    expect(f.length).toBe(1);
    expect(f[0].message).toContain('carries the placeholder "TBD"');
  });

  it("heading text is trimmed after entity decoding", () => {
    expect(checkBody(healthy.replace("## Tests", "## Tests&#32;"))).toEqual([]);
  });

  it("an adjacent duplicate of the final section is DUP but never ORDER", () => {
    const f = checkBody(`${healthy}\n## Post-deployment validation\n\nagain\n`);
    expect(rules(f)).toEqual(["PRX-B-SECTION-DUP"]);
  });

  it("a labeled fence containing narrative prose is not flagged", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```text\nThis prose sentence has many words in it.\n```"
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("capsule grammar is enforced per key: Scope, Run-Id, Ledger, and the shared length bound", () => {
    const trips = (from: string, to: string) =>
      checkBody(healthy.replace(from, to)).some(
        x => x.rule === "PRX-B-CAPSULE"
      );
    expect(trips("Scope: TOS-123", "Scope: not-a-scope")).toBe(true);
    expect(trips("Run-Id: ONE-20260812-PRX", "Run-Id: BAD-ID")).toBe(true);
    expect(trips("Ledger: UNKNOWN", "Ledger: nope!")).toBe(true);
    const atBound = healthy.replace(
      "Evidence: UNKNOWN",
      `Evidence: docs/${"a".repeat(115)}`
    );
    expect(checkBody(atBound)).toEqual([]);
  });

  it("content after a depth-3 subheading still fills the section", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n### details\n\nReal text under sub."
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("a whitespace-only fenced block is not section content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```\n  \n```"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("raw HTML with visible text fills a section", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n<div>Real text</div>"
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("raw HTML whose visible text is only whitespace is not content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n<div> </div>"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("a list item containing only a subheading is not meaningful content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n- ### h"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("a blockquote containing only a subheading is not meaningful content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n> ### h"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("a paragraph that decodes to only whitespace is not content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n&#32;"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("image REFERENCE alt text counts as visible content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n![ref alt][r]\n\n[r]: https://example.com"
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("an HTML comment containing '>' inside an HTML block is fully invisible", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n<div></div><!-- >text -->"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("adjacent label-less links are still empty content", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n[](https://a.example)[](https://b.example)"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("an empty unlabeled fence is empty content but never narrative", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```\n```"
    );
    expect(rules(checkBody(body))).toEqual(["PRX-B-SECTION-EMPTY"]);
  });

  it("an unlabeled fence of bullet lines trips PRX-B-FENCE", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```\n- alpha\n- beta\n```"
    );
    expect(checkBody(body).some(x => x.rule === "PRX-B-FENCE")).toBe(true);
  });

  it("an unlabeled fence of multi-digit ordered items trips PRX-B-FENCE", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```\n12. twelve here\n13. thirteen here\n```"
    );
    expect(checkBody(body).some(x => x.rule === "PRX-B-FENCE")).toBe(true);
  });

  it("an unlabeled fence of plain non-narrative lines is not flagged", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```\nx = 1\nword - dash\nab- c\nnote. done\nfour plain words here\ne.g. four words here maybe\nupgrade to version v1.0\n   Three word sentence.\nup  and  down.\n```"
    );
    expect(checkBody(body)).toEqual([]);
  });

  it("an unlabeled fence holding a four-word sentence trips PRX-B-FENCE", () => {
    const body = healthy.replace(
      "## Bundle impact\n\nnone",
      "## Bundle impact\n\n```\nExactly four words total.\n```"
    );
    expect(checkBody(body).some(x => x.rule === "PRX-B-FENCE")).toBe(true);
  });

  it("a list nested two blockquotes deep is still detected as structure", () => {
    const f = checkBody(healthy + "\n> > - hidden item\n");
    expect(f.some(x => x.rule === "PRX-B-STRUCTURE")).toBe(true);
  });

  it("non-string input is bounced by the size/type guard, fast", () => {
    // Deterministic, sub-millisecond kill for the size-guard conditional:
    // without the guard, null reaches raw.length and throws.
    expect(rules(checkBody(null as unknown as string))).toEqual(["PRX-B-SIZE"]);
  });

  it("only depth-2 HEADINGS enter the section index", () => {
    // A paragraph-only body must yield exactly the 14 missing-section
    // errors — a corrupted heading filter would surface the paragraph as
    // an extension heading (PRX-B-EXT) alongside them.
    const f = checkBody("Just a paragraph.");
    expect(f.filter(x => x.rule === "PRX-B-EXT")).toEqual([]);
    expect(f.filter(x => x.rule === "PRX-B-SECTION-MISSING").length).toBe(14);
  });

  it("non-key capsule lines are quoted verbatim up to 60 chars and truncated beyond", () => {
    const body = healthy.replace(
      "Evidence: UNKNOWN",
      `Evidence: UNKNOWN\nSurprise: extra\n${"Z".repeat(80)}\n${"Y".repeat(60)}`
    );
    const msgs = checkBody(body)
      .filter(x => x.rule === "PRX-B-CAPSULE")
      .map(x => x.message);
    expect(msgs.some(m => m.includes('non-key line: "Surprise: extra"'))).toBe(
      true
    );
    expect(msgs.some(m => m.includes(`${"Z".repeat(57)}...`))).toBe(true);
    expect(msgs.every(m => !m.includes("Z".repeat(58)))).toBe(true);
    expect(msgs.some(m => m.includes(`"${"Y".repeat(60)}"`))).toBe(true);
  });
});

describe("focused-review fixes (capsule labeling + hard breaks)", () => {
  it("a LABELED fence quoting a governed commit is never a capsule candidate", () => {
    // Quoting `git log` output of a governed commit (with its mandated
    // trailers) inside a ```text fence must not be torn apart by the
    // strict capsule validator (review finding, HIGH).
    const quoted =
      "```text\nfeat(x): ship the thing\n\nWhy.\n\nRun-Id: ONE-20260812-PRX\n" +
      "Evidence: UNKNOWN\nCo-Authored-By: A B <a@b.co>\n```";
    const body = healthy.replace(
      "## Reproduction evidence\n\nnone",
      `## Reproduction evidence\n\n${quoted}`
    );
    const f = checkBody(body);
    expect(f.filter(x => x.rule === "PRX-B-CAPSULE")).toEqual([]);
  });

  it("the real capsule (a BARE fence) is still validated strictly", () => {
    const body = healthy.replace("Scope: TOS-123", "Scope: junk");
    expect(checkBody(body).some(x => x.rule === "PRX-B-CAPSULE")).toBe(true);
  });

  it("a Unicode bullet after a hard line break is still detected", () => {
    const f = checkBody(`${healthy}\nline one  \n• bullet two\n`);
    expect(f.some(x => x.rule === "PRX-B-STRUCTURE")).toBe(true);
  });
});

